        gsl = ctypes.CDLL("usr/local/gsl/lib/libgsl.so")
        gsl_sf_result = ctypes.POINTER(ctypes.c_double)()
        gsl.gsl_sf_transport_2.argtypes = [ctypes.c_double, ctypes.POINTER(ctypes.c_double)]
        gsl.gsl_sf_transport_2.restype = None
