class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return self.func(x)

class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = np.zeros((size,), dtype=np.float64)

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    # Create the GSL function wrapper
gsl_function = GSLFunction(func)

# Create the CQuadWorkspace object
workspace = CQuadWorkspace(workspace_size)

# Initialize the integration variables
result = np.zeros((2,), dtype=np.float64)
error = np.zeros((1,), dtype=np.float64)

gsl.gsl_integration_cquad(ctypes.pointer(result), ctypes.pointer(error), gsl_function, a, b, epsabs, epsrel, workspace.workspace)

# Return the computed integral, estimated absolute error, and number of function evaluations
return (result[0], error[0], int(workspace.size))

