class gsl_sum_levin_utrunc_workspace:
    def __init__(self, n):
        self.size = n

        self.gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        self.allocate = self.gsl.gsl_sum_levin_utrunc_alloc
        self.deallocate = self.gsl.gsl_sum_levin_utrunc_free

    def allocate_and_free(self, n):
        try:
            self.workspace = self.allocate(ctypes.c_size_t(n))
            if not self.workspace:
                raise RuntimeError("Failed to allocate workspace for Levin u-transform summation")
            return True
        except:
            return False

    def free(self):
        try:
            self.deallocate(self.workspace)
            return True
        except:
            return False

