from ctypes import *

class gsl_sf_result(Structure):
    _fields_ = [("val", c_double), ("err", c_double)]

class gsl_sf_result_e10(Structure):
    _fields_ = [("val", c_double), ("err", c_double), ("e10", c_int)]

