gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def smash_result(input_dict):
    result = gsl.smash_result(byref(gsl_sf_result_e10(*input_dict.values())))
    return {"val": result.contents.val, "err": result.contents.err}

