class gsl_combination(ctypes.Structure):
    pass

def create_first_combination(n, k):
    # Load GSL libraries
    try:
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        return None

    # Allocate a combination for given n and k values
    try:
        combination = gsl_combination()
        gsl.gsl_combination_alloc(ctypes.c_size_t(n), ctypes.c_size_t(k), ctypes.byref(combination))
    except ValueError:
        return None

    # Initialize the combination to the first combination (smallest lexicographical order)
    try:
        gsl.gsl_combination_init_first(ctypes.c_void_p(combination))
    except OSError:
        return None

    # Extract the combination data as a Python list
    data = []
    for i in range(k):
        data.append(gsl.gsl_combination_get_data(ctypes.c_void_p(combination), ctypes.c_size_t(i)))

    # Free the combination object
    gsl.gsl_combination_free(ctypes.c_void_p(combination))

    return data

