class CMedianAccumulator:
    def __init__(self, window_size):
        self.window_size = window_size
        self.data = []

    def insert(self, value):
        self.data.append(value)

    def retrieve(self):
        if len(self.data) < self.window_size:
            return None
        else:
            return sum(self.data[-self.window_size:]) / float(self.window_size)

def compute_moving_median(data, window_size):
    accumulator = CMedianAccumulator(window_size)
    medians = []
    for value in data:
        accumulator.insert(value)
        medians.append(accumulator.retrieve())
    return medians

