import ctypes

def find_minmax_indices(matrix):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl_matrix_minmax_index = gsl.gsl_matrix_minmax_index

    matrix_ptr = (ctypes.c_float * len(matrix))(*matrix)
    gsl_matrix = GSLMatrix(matrix_ptr, len(matrix), len(matrix[0]))

    min_idx = ctypes.c_size_t()
    max_idx = ctypes.c_size_t()
    gsl_matrix_minmax_index(gsl_matrix, ctypes.byref(min_idx), ctypes.byref(max_idx))

