import ctypes

class GSL():
    def __init__(self):
        self.gsl = None
        self.gslcblas = None

    def load_libs(self, libdir="/usr/local/gsl/lib"):
        self.gslcblas = ctypes.CDLL("{libdir}/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("{libdir}/libgsl.so")

    def gsl_cdf_beta_P(self, x, a, b):
        # Load the GSL libraries if not already loaded
        if self.gsl is None or self.gslcblas is None:
            self.load_libs()

        # Define the C function signatures
        gsl_cdf_beta_P = self.gsl.gsl_cdf_beta_P
        gsl_cdf_beta_P.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double]
        gsl_cdf_beta_P.restype = ctypes.c_double

        # Call the C function
        return gsl_cdf_beta_P(x, a, b)

    def gsl_cdf_beta_Q(self, x, a, b):
        # Load the GSL libraries if not already loaded
        if self.gsl is None or self.gslcblas is None:
