import ctypes

class GSL:
    def __init__(self):
        self.lib = None

    def _load_library(self, library_path):
        if self.lib is not None:
            return
        try:
            self.lib = ctypes.CDLL(library_path, mode=ctypes.RTLD_GLOBAL)
        except OSError as e:
            print("Failed to load GSL library", e)

    def gsl_cdf_beta_P(self, x, a, b):
        if self.lib is None:
            self._load_library("/usr/local/gsl/lib/libgslcblas.so")
        if self.lib is None:
            self._load_library("/usr/local/gsl/lib/libgsl.so")
        if self.lib is not None:
            func = self.lib.gsl_cdf_beta_P
            func.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double]
            func.restype = ctypes.c_double
            return func(x, a, b)
        else:
            return 0

    def gsl_cdf_beta_Q(self, x, a, b):
        if self.lib is None:
            self._load_library("/usr/local/gsl/lib/libgslcblas.so")
        if self.lib is None:
            self._load_library("/usr/local/gsl/lib/libgsl.so")
        if self.lib is not None:
            func = self.lib.gsl_cdf_beta_Q
            func.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double]
            func.restype = ctypes.c_double
            return func(x, a, b)
        else:
            return 0

