    for i in range(gsl_matrix.size1):
        row = []
        for j in range(gsl_matrix.size2):
            row.append(gsl_matrix.matrix[i * gsl_matrix.size2 + j])
        numpy_matrix.append(row)
    return numpy_matrix

def compute_matrix_exponential(matrix, mode):
    # Load GSL libraries
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Convert input matrix to GSL format
    gsl_matrix = matrix_to_gsl(matrix)

    # Compute matrix exponential using GSL function
    gsl_exponential = gsl.gsl_linalg_exponential_ss(gsl_matrix, mode)

    # Convert result back to NumPy format
    numpy_exponential = gsl_matrix_to_numpy(gsl_exponential)

    return numpy_exponential

