def test_compute_matrix_exponential():
    matrix = [[1, 2], [3, 4]]
    mode = 0
    result = compute_matrix_exponential(matrix, mode)
    expected = [[-0.65361391, -1.30622783], [-2.08333333, -3.46666667]]
    assert result == expected

