def extract_subvector(vector, start, length):
    if not isinstance(vector, GSLVector) or not isinstance(start, int) or not isinstance(length, int):
        raise TypeError("Invalid input type")
    if start < 0 or length <= 0:
        raise ValueError("Invalid input value")
