class GSLVector:
    def __init__(self, gsl, data):
        self.gsl = gsl
        self.data = data

    @property
    def size(self):
        return len(self.data)

    def __getitem__(self, key):
        if isinstance(key, int):
            return self.data[key]
        elif isinstance(key, slice):
            start = key.start or 0
            stop = key.stop or self.size
            step = key.step or 1
            if step == 1:
                return [self.data[i] for i in range(start, stop)]
            else:
                return [self.data[i * step + start] for i in range((stop - start) // step)]
        else:
            raise TypeError("Invalid index type")

    def __setitem__(self, key, value):
        if isinstance(key, int):
            self.data[key] = value
        elif isinstance(key, slice):
            start = key.start or 0
            stop = key.stop or self.size
            step = key.step or 1
            if step == 1:
                for i in range(start, stop):
                    self.data[i] = value[i - start]
            else:
                for i, v in enumerate((value[i * step + start] for i in range((stop - start) // step))):
                    self.data[i] = v
        else:
            raise TypeError("Invalid index type")

class GSLVectorView(GSLVector):
    def __init__(self, gsl, vector, start, length):
        super().__init__(gsl, [])
        self.vector = vector
        self.start = start
        self.length = length

    @property
    def size(self):
        return self.length

    def __getitem__(self, key):
        if isinstance(key, int):
            return self.vector[self.start + key]
        elif isinstance(key, slice):
            start = key.start or 0
            stop = key.stop or self.length
            step = key.step or 1
            if step == 1:
                return [self.vector[i] for i in range(self.start + start, self.start + stop)]
            else:
                return [self.vector[i * step + self.start] for i in range((stop - start) // step)]
        else:
            raise TypeError("Invalid index type")

